import{_ as a,o as s,c as t,a2 as o}from"./chunks/framework.C2TvIV46.js";const m=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"language/index.md","filePath":"language/index.md"}'),n={name:"language/index.md"};function l(r,e,i,d,g,c){return s(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><h2 id="foreword" tabindex="-1">Foreword <a class="header-anchor" href="#foreword" aria-label="Permalink to &quot;Foreword&quot;">​</a></h2><p>Megalo was designed in March 2008 by Bungie&#39;s Tyson Green as a data-driven system for implementing Halo multiplayer game rules. End-user Megalo tooling was an objective from the start, but it was something Bungie never shipped during Reach&#39;s original development.</p><p>Since then, Halo Studios has released Bungie&#39;s <strong>MegaloEdit.exe</strong> with the Halo Reach Editing Kit (HREK), enabling players to build their own scripts. Little documentation has accompanied that tooling.</p><p>This documentation is the result of an extensive study of Halo: Reach Megalo. It deliberately follows Bungie&#39;s own <a href="https://martinfowler.com/bliki/UbiquitousLanguage.html" target="_blank" rel="noreferrer">Ubiquitous Language</a> — naming things as Bungie would have named them, using the same vocabulary found in shipped scripts and the MegaloEdit tooling.</p><p>I would like to give my thanks to those modders who worked tirelessly to understand Megalo and make cool gametypes with it in the last 16 years including <a href="https://github.com/KornnerStudios" target="_blank" rel="noreferrer">kornman</a>, <a href="https://github.com/DavidJCobb/ReachVariantEditor" target="_blank" rel="noreferrer">DavidJCobb</a>, <a href="https://github.com/Pfoiffee" target="_blank" rel="noreferrer">Pfoiffee</a>, <a href="https://github.com/Sopitive" target="_blank" rel="noreferrer">Soptive</a> and countless others I have not had the pleasure of meeting. - Codie</p><h2 id="what-is-megalo" tabindex="-1">What is Megalo? <a class="header-anchor" href="#what-is-megalo" aria-label="Permalink to &quot;What is Megalo?&quot;">​</a></h2><p><strong>Megalo</strong> is the scripting language Bungie built for Halo: Reach multiplayer rules. Authors edit human-readable <code>.txt</code> scripts with a Megalo-aware editor; Bungie shipped <strong>MegaloEdit.exe</strong> with Reach. We recommend <strong>MegaloEvolved</strong> as a free and open-source alternative.</p><p>Megalo is not a general-purpose language. It has no functions, loops, or arbitrary expressions — only the condition and action vocabulary the engine exposes, organized into <strong>triggers</strong> that fire on game events.</p><p>A Megalo program is a sequence of <strong>elements</strong> that describe a gametype or custom map variant:</p><table tabindex="0"><thead><tr><th>Concept</th><th>Role</th></tr></thead><tbody><tr><td><strong>Elements</strong></td><td>Block and leaf keywords at the script root — metadata, teams, variables, triggers, HUD widgets, string tables, and more. See <a href="/MegaloEvolved/beta/docs/language/syntax#the-element-model">The element model</a>; individual pages are listed under <strong>Elements</strong> in the sidebar.</td></tr><tr><td><strong>Triggers</strong></td><td>Event handlers. Each trigger runs when its <strong>conditions</strong> are satisfied, then executes its <strong>actions</strong>. See <a href="/MegaloEvolved/beta/docs/language/elements/trigger">trigger</a>.</td></tr><tr><td><strong>Conditions</strong></td><td>Predicates such as <code>if</code>, <code>player_died</code>, <code>timer_expired</code>, or <code>object_in_area</code>. See <a href="/MegaloEvolved/beta/docs/language/elements/trigger/condition">condition</a>.</td></tr><tr><td><strong>Actions</strong></td><td>Imperative statements — <code>set</code>, <code>create_object</code>, <code>hud_post_message</code>, <code>for_each</code>, and dozens of others. See <a href="/MegaloEvolved/beta/docs/language/elements/trigger/action">action</a>.</td></tr><tr><td><strong>Variables</strong></td><td>Typed slots (<code>number</code>, <code>timer</code>, <code>object</code>, <code>team</code>, <code>player</code>) scoped to global, team, player, or object storage. See <a href="/MegaloEvolved/beta/docs/language/variable-model">Variable model</a>.</td></tr><tr><td><strong>References</strong></td><td>Symbolic operands that identify players, teams, objects, timers, and custom variables at runtime. See <a href="/MegaloEvolved/beta/docs/language/references">References</a>.</td></tr></tbody></table><h2 id="source-files" tabindex="-1">Source files <a class="header-anchor" href="#source-files" aria-label="Permalink to &quot;Source files&quot;">​</a></h2><p>Megalo editors store scripts as plain text. A typical gametype script begins with metadata and ends with triggers:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">include</span><span class="megalo-text"> </span><span class="megalo-string">&quot;strings/slayer_strings.txt&quot;</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">engine_data</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">name</span><span class="megalo-text"> slayer_title</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">description</span><span class="megalo-text"> slayer_description</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">icon</span><span class="megalo-text"> k_engine_icon_slayer</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">category</span><span class="megalo-text"> slayer</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">variables</span><span class="megalo-text"> </span><span class="megalo-keyword">global</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">local</span><span class="megalo-text"> </span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">my_counter</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-enumMember">initialization</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">set</span><span class="megalo-text"> </span><span class="megalo-variable">my_counter</span><span class="megalo-text"> </span><span class="megalo-keyword">set_to</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>Scripts can <code>include</code> other files; the editor merges includes before compile. Some scripts also declare a <code>base</code> to inherit from a compiled parent variant — see <a href="/MegaloEvolved/beta/docs/language/base-files">Base files</a>.</p><p>The exact set of valid conditions and actions depends on the Reach build. See <a href="/MegaloEvolved/beta/docs/versions/">Megalo Versions</a> for per-build tables.</p><h2 id="reading-guide" tabindex="-1">Reading guide <a class="header-anchor" href="#reading-guide" aria-label="Permalink to &quot;Reading guide&quot;">​</a></h2><p>Work through these pages in order, or jump to a topic:</p><ol><li><a href="/MegaloEvolved/beta/docs/language/syntax">Syntax &amp; file format</a> — comments, tokens, naming, includes, <a href="/MegaloEvolved/beta/docs/language/syntax#the-element-model">element model</a></li><li><a href="/MegaloEvolved/beta/docs/language/base-files">Base files</a> — inheriting from a compiled parent variant</li><li><a href="/MegaloEvolved/beta/docs/language/variable-model">Variable model</a> — types, scopes, constants, built-ins</li><li><a href="/MegaloEvolved/beta/docs/language/elements/trigger">trigger</a> — kinds, action scope, execution, <code>for_each</code></li><li><a href="/MegaloEvolved/beta/docs/language/elements/trigger/condition">condition</a> — comparisons, events, <code>and</code> / <code>or</code>, negation</li><li><a href="/MegaloEvolved/beta/docs/language/elements/trigger/action">action</a> — opcodes, <code>set</code>, <a href="/MegaloEvolved/beta/docs/language/enums/math-operations">math operations</a>, action families</li><li><a href="/MegaloEvolved/beta/docs/language/references">References</a> — player, team, object, timer operands; see also <a href="/MegaloEvolved/beta/docs/language/enums/dynamic-strings">dynamic strings</a></li><li><a href="/MegaloEvolved/beta/docs/language/examples">Example scripts</a> — annotated walkthroughs of minimal scripts</li><li><a href="/MegaloEvolved/beta/docs/language/object-lists">Object lists</a> — engine lookup tables for symbolic names</li><li><a href="/MegaloEvolved/beta/docs/language/compiler-settings">Compiler settings</a> — compile-time strictness and temporary overflow</li></ol><p>For using the TypeScript library, see the <a href="/MegaloEvolved/beta/docs/guide/quick-start">usage guide</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/MegaloEvolved/beta/docs/versions/">Megalo Versions &amp; action tables</a></li><li><a href="/MegaloEvolved/beta/docs/guide/megalo-versions">Megalo versions (MCC vs TU1)</a></li></ul>`,22)])])}const h=a(n,[["render",l]]);export{m as __pageData,h as default};
